type PriceSummaryProps = {
  basePrice: number;
  optionsPrice: number;
};

export function PriceSummary({ basePrice, optionsPrice }: PriceSummaryProps) {
  const total = basePrice + optionsPrice;

  return (
    <aside className="price-summary">
      <dl>
        <dt>기본 차량 가격</dt>
        <dd>{formatKrw(basePrice)}</dd>
        <dt>선택된 옵션 가격</dt>
        <dd>{formatKrw(optionsPrice)}</dd>
      </dl>
      <strong>예상 총액 {formatKrw(total)}</strong>
    </aside>
  );
}

