export function isWheelAllowed(model, wheel, matrix) {
  const allowed = matrix[model]?.wheels ?? [];
  return allowed.includes(wheel);
}

export function selectWheel(state, wheel, matrix) {
  if (!isWheelAllowed(state.model, wheel, matrix)) {
    return { ...state, conflictModal: { wheel } };
  }
  return { ...state, wheel, conflictModal: null };
}

type SelectedOption = {
  id: string;
  name: string;
  price: number;
};

export function calculateTotal(
  basePrice: number,
  options: SelectedOption[]
): number {
  return options.reduce((sum, option) => sum + option.price, basePrice);
}

.price-summary__options:empty::after {
  content: "선택한 유료 옵션이 없습니다.";
  color: #7d8590;
  font-size: 12px;
}

const REQUIRED_MESSAGES = {
  name: "이름을 입력해주세요.",
  email: "이메일을 입력해주세요.",
  phone: "연락처를 입력해주세요.",
  consent: "개인정보 수집 및 이용에 동의해주세요.",
};

export function FormErrors({ errors }) {
  return (
    <ul className="form-errors">
      {Object.entries(REQUIRED_MESSAGES)
        .filter(([field]) => errors[field])
        .map(([field, message]) => (
          <li key={field} role="alert">{message}</li>
        ))}
    </ul>
  );
}
